(() => {
  'use strict';
  const API = '/api';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const state = {token:sessionStorage.getItem('zapia_token')||'', role:sessionStorage.getItem('zapia_role')||'', tenant:sessionStorage.getItem('zapia_tenant')||'', tenantId:sessionStorage.getItem('zapia_tenant_id')||'', route:'dashboard', summary:null, conversations:[], selectedConversation:null};
  const labels = {dashboard:'Visão geral',agents:'Agentes',instances:'Conexões WhatsApp',conversations:'Conversas',knowledge:'Conhecimento',model:'Modelo IA',tenants:'Empresas',settings:'Configurações'};
  function toast(message,type='') { const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=message; $('#toast-region').append(el); setTimeout(()=>el.remove(),4800); }
  async function request(path,{method='GET',body,form=false}={}) {
    const headers={}; if(state.token) headers.Authorization=`Bearer ${state.token}`; if(state.tenantId) headers['X-Tenant-ID']=state.tenantId;
    if(body!==undefined && !form) headers['Content-Type']='application/json';
    const response=await fetch(API+path,{method,headers,body:body===undefined?undefined:form?body:JSON.stringify(body)});
    let data=null; const text=await response.text(); if(text){try{data=JSON.parse(text)}catch{data={message:text}}}
    if(!response.ok){const msg=data?.detail||data?.message||`Erro HTTP ${response.status}`; throw new Error(typeof msg==='string'?msg:Array.isArray(msg)?msg.map(item=>`${({name:'Nome da empresa',slug:'Slug',owner_name:'Nome do responsável',owner_email:'E-mail do responsável',owner_password:'Senha do responsável'})[item.loc?.at(-1)]||item.loc?.at(-1)||'Campo'}: ${item.msg||'valor inválido'}`).join('; '):`Erro HTTP ${response.status}`)}
    return data;
  }
  function setLoggedIn(on){$('#login-view').hidden=on;$('#app-view').hidden=!on;if(on){$('#tenant-name').textContent=state.tenant||'Seu espaço';$('#tenants-nav').hidden=state.role!=='platform_admin';$('#user-avatar').textContent=(state.tenant||'U').trim().charAt(0).toUpperCase();}}
  function loading(){return '<div class="loading"><span class="spinner" aria-hidden="true"></span>Carregando dados…</div>';}
  function pageHead(title,subtitle,action=''){return `<div class="page-head"><div><p class="eyebrow">ATENDIMENTO HUMANO NO WHATSAPP</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
  function empty(title,desc,action=''){return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">◇</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;}
  function errorBox(err){return `<div class="inline-alert" role="alert"><strong>Não foi possível carregar.</strong> ${esc(err.message||err)}. Confira a API e tente novamente.</div><button class="button button-secondary" data-retry>↻ Tentar novamente</button>`;}
  function notice(){return `<div class="notice"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><strong>Conexões WhatsApp: respostas automáticas ficam desligadas até configuração e ativação</strong>Configure o provedor da empresa e ative as respostas automáticas explicitamente nas configurações do agente.</div></div>`;}
  function go(route){if(route==='tenants'&&state.role!=='platform_admin'){toast('Acesso restrito a administradores da plataforma.','error');route='dashboard'}state.route=route;location.hash=route;render();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
  function wireNav(){ $$('[data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();go(a.dataset.route)})); $('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open))}; $('#logout-btn').onclick=logout; }
  function logout(){sessionStorage.removeItem('zapia_token');sessionStorage.removeItem('zapia_role');sessionStorage.removeItem('zapia_tenant');sessionStorage.removeItem('zapia_tenant_id');state.token='';state.role='';state.tenant='';state.tenantId='';setLoggedIn(false);$('#login-form').reset();}
  function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();$('#modal-body').querySelector('input:not([type=checkbox]),textarea,select')?.focus();}
  function closeModal(){const dialog=$('#modal');if(dialog.open)dialog.close();$('#modal-body').innerHTML='';}
  let modalBackdropPress=false;
  $('#modal').addEventListener('pointerdown',e=>{modalBackdropPress=e.target===$('#modal')});
  $('#modal').addEventListener('click',e=>{
    if(e.target.closest('[data-close-modal]')){closeModal();return}
    if(e.target===$('#modal')&&modalBackdropPress)closeModal();
    modalBackdropPress=false;
  });
  function askConfirm(message,{title='Confirmar',confirmLabel='Continuar',cancelLabel='Cancelar',danger=false}={}){
    return new Promise(resolve=>{
      const dialog=$('#confirm-dialog'),ok=$('#confirm-ok'),cancel=$('#confirm-cancel');
      let settled=false;
      const finish=value=>{if(settled)return;settled=true;ok.onclick=cancel.onclick=null;dialog.oncancel=null;if(dialog.open)dialog.close();resolve(value)};
      $('#confirm-title').textContent=title;
      $('#confirm-message').textContent=message;
      cancel.textContent=cancelLabel;
      ok.textContent=confirmLabel;
      ok.className=danger?'button button-danger':'button button-primary';
      ok.onclick=()=>finish(true);
      cancel.onclick=()=>finish(false);
      dialog.oncancel=e=>{e.preventDefault();finish(false)};
      dialog.showModal();
      ok.focus();
    });
  }
  async function formSubmit(form,fn){form.addEventListener('submit',async e=>{e.preventDefault();let error=form.querySelector('[data-form-error]');if(!error){error=document.createElement('p');error.className='inline-alert';error.dataset.formError='';error.setAttribute('role','alert');error.tabIndex=-1;form.querySelector('.form-actions')?.before(error);if(!error.isConnected)form.append(error)}error.hidden=true;error.textContent='';const button=form.querySelector('[type=submit]');const label=button.textContent;button.disabled=true;button.innerHTML='<span class="spinner"></span>Salvando…';try{await fn(new FormData(form));}catch(err){error.textContent=err.message||'Falha ao salvar.';error.hidden=false;error.focus()}finally{if(button.isConnected){button.disabled=false;button.textContent=label}}});}
  function render(){if(!state.token){setLoggedIn(false);return}setLoggedIn(true);let route=location.hash.slice(1);if(state.role==='platform_admin'&&!state.tenantId&&route!=='tenants'){route='tenants';state.route='tenants';location.hash='tenants';} if(labels[route]&&(route!=='tenants'||state.role==='platform_admin'))state.route=route;const r=state.route;$('#page-crumb').textContent=labels[r]||labels.dashboard;$$('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===r));$('#page-content').innerHTML=loading();$('#page-content').focus({preventScroll:true});({dashboard:dashboard,agents:agents,instances:instances,conversations:conversations,knowledge:knowledge,model:model,tenants:tenants,settings:settings}[r]||dashboard)();}
  async function dashboard(){let root=$('#page-content');try{const d=await request('/dashboard/summary');state.summary=d||{};if(state.route!=='dashboard')return;const counts=d?.counts||d||{};const agentCount=counts.agents??counts.total_agents;const instanceCount=counts.instances??counts.zapi_instances;const openConvs=counts.open_conversations??counts.conversations;const active=counts.active_agents;root.innerHTML=pageHead('Visão geral','Acompanhe a operação do seu atendimento.')+notice()+`<div class="grid summary-grid">${metric('Agentes',agentCount,'Agentes cadastrados','✳')}${metric('Conexões WhatsApp',instanceCount,'Conexões disponíveis','◉')}${metric('Conversas abertas',openConvs,'Atendimentos em andamento','☷')}${metric('Agentes ativos',active,'Status da operação','↗')}</div><div class="grid dashboard-grid"><section class="card panel"><div class="panel-head"><div><h2>Status da operação</h2><p>Indicadores recebidos da sua conta.</p></div><span class="badge badge-teal">Tempo real</span></div><div class="status-row"><div class="status-label"><span class="status-dot status-neutral"></span><span><strong>Transporte WhatsApp</strong><small>Configure uma conexão WhatsApp para ativar o atendimento</small></span></div><span class="badge badge-warn">Verificar conexão</span></div><div class="status-row"><div class="status-label"><span class="status-dot status-neutral"></span><span><strong>Respostas automáticas</strong><small>Controle explícito por agente</small></span></div><span class="badge badge-warn">Desligadas por padrão</span></div></section><section class="card panel"><div class="panel-head"><div><h2>Comece por aqui</h2><p>Configure seu atendimento.</p></div></div><div class="status-row"><span class="status-label"><span class="metric-icon">◉</span><span><strong>Conecte o WhatsApp</strong><small>Adicione as credenciais do provedor</small></span></span><button class="small-button" data-go="instances">Abrir</button></div><div class="status-row"><span class="status-label"><span class="metric-icon">✳</span><span><strong>Configure um agente</strong><small>Defina comportamento e ativação</small></span></span><button class="small-button" data-go="agents">Abrir</button></div></section></div>`;$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}catch(err){if(state.route==='dashboard')root.innerHTML=pageHead('Visão geral','Acompanhe a operação do seu atendimento.')+notice()+errorBox(err);}}
  function metric(title,value,note,icon){return `<article class="metric-card"><div class="metric-label">${esc(title)}<span class="metric-icon" aria-hidden="true">${icon}</span></div><div class="metric-value">${value==null?'—':esc(value)}</div><div class="metric-note">${value==null?'Sem dado fornecido pela API':esc(note)}</div></article>`;}
  function table(headers,rows,emptyText='Nenhum registro encontrado.'){return `<div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>${rows?'':empty('Nada por aqui ainda',emptyText)}</div>`;}
  async function agents(){const root=$('#page-content');const action='<button class="button button-primary" data-add-agent>＋ Novo agente</button>';root.innerHTML=pageHead('Agentes','Gerencie o comportamento e a ativação dos seus agentes.',action)+loading();root.querySelector('[data-add-agent]').onclick=()=>agentForm();try{const data=await request('/agents');const arr=Array.isArray(data)?data:(data?.items||[]);if(state.route!=='agents')return;const rows=arr.map(a=>`<tr><td><strong>${esc(a.name||a.label||'Agente')}</strong></td><td>${esc(a.description||'—')}</td><td>${a.auto_reply_enabled?'<span class="badge badge-good">Ativada</span>':'<span class="badge">Desligada</span>'}</td><td>${a.enabled?'<span class="badge badge-good">Ativo</span>':'<span class="badge">Inativo</span>'}</td><td><div class="actions"><button class="small-button" data-edit="${esc(a.id)}">Editar</button><button class="small-button" data-style="${esc(a.id)}">Tom e conversa</button><button class="small-button" data-delete="${esc(a.id)}">Excluir</button></div></td></tr>`).join('');root.innerHTML=pageHead('Agentes','Gerencie o comportamento e a ativação dos seus agentes.',action)+notice()+table(['Agente','Descrição','Auto-resposta','Status','Ações'],rows,'Crie seu primeiro agente para começar.');root.querySelector('[data-add-agent]').onclick=()=>agentForm();$$('[data-style]',root).forEach(b=>b.onclick=()=>conversationProfileForm(b.dataset.style));$$('[data-edit]',root).forEach(b=>b.onclick=()=>agentForm(arr.find(a=>String(a.id)===b.dataset.edit)));$$('[data-delete]',root).forEach(b=>b.onclick=()=>confirmDelete('agente',b.dataset.delete,agents));}catch(err){if(state.route==='agents')root.innerHTML=pageHead('Agentes','Gerencie o comportamento e a ativação dos seus agentes.',action)+errorBox(err);}}
  async function agentForm(a={}){let models;try{models=await llmUI.connections()}catch(e){toast('Não foi possível carregar as conexões de IA: '+e.message,'error');return}openModal(a.id?'Editar agente':'Novo agente',`<form id="agent-form"><div class="form-grid"><div class="form-field"><label class="field-label" for="agent-name">Nome</label><input class="field-control" id="agent-name" name="name" required value="${esc(a.name||'')}"></div><div class="form-field"><label class="field-label" for="agent-enabled">Status</label><select class="field-control" id="agent-enabled" name="enabled"><option value="true" ${a.enabled!==false?'selected':''}>Ativo</option><option value="false" ${a.enabled===false?'selected':''}>Inativo</option></select></div></div><label class="field-label" for="agent-description">Descrição</label><textarea class="field-control" id="agent-description" name="description">${esc(a.description||'')}</textarea><label class="field-label" for="agent-prompt">Instruções do agente</label><textarea class="field-control" id="agent-prompt" name="system_prompt">${esc(a.system_prompt||'')}</textarea><label class="check-line"><input type="checkbox" name="auto_reply_enabled" value="true" ${a.auto_reply_enabled===true?'checked':''}><span><strong>Ativar auto-resposta</strong><br><span class="muted-text">Começa desligada. Ative somente após configurar a conexão e testar o agente.</span></span></label>${llmUI.agentFields(a,models)}<div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Salvar agente</button></div></form>`);const f=$('#agent-form');const bindings=llmUI.wireAgentForm(f,a,models);formSubmit(f,async fd=>{const payload={...bindings(),name:fd.get('name'),description:fd.get('description'),system_prompt:fd.get('system_prompt'),enabled:fd.get('enabled')==='true',auto_reply_enabled:fd.get('auto_reply_enabled')==='true'};await request(a.id?`/agents/${encodeURIComponent(a.id)}`:'/agents',{method:a.id?'PUT':'POST',body:payload});closeModal();toast('Agente salvo.','success');agents()});}
  async function conversationProfileForm(id){
    try{
      const p=await request(`/agents/${encodeURIComponent(id)}/conversation-policy`);
      openModal('Tom e conversa',`<form id="conversation-profile-form">
        <label class="check-line"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Habilitar perfil de estilo conversacional para este agente</label>
        <label class="check-line"><input type="checkbox" name="visit_booking_enabled" ${p.visit_booking_enabled?'checked':''}> Este agente qualifica e encaminha pedidos de visita técnica</label>
        <label class="field-label">Tom<select class="field-control" name="tone"><option value="neutral">Neutro</option><option value="formal">Formal</option><option value="friendly">Próximo e respeitoso</option></select></label>
        <label class="field-label">Detalhamento<select class="field-control" name="conciseness"><option value="short">Curto</option><option value="balanced">Equilibrado</option><option value="detailed">Detalhado</option></select></label>
        <label class="field-label">Emojis<select class="field-control" name="emojis"><option value="none">Sem emojis</option><option value="sparing">Com moderação</option></select></label>
        <label class="field-label">Validade do contexto em minutos<input class="field-control" name="context_minutes" type="number" min="5" max="1440" value="${esc(p.context_minutes)}" required></label>
        <label class="field-label">Máximo de espera por fragmentos (segundos)<input class="field-control" name="max_wait_seconds" type="number" min="3" max="60" value="${esc(p.max_wait_seconds)}" required></label>
        <p class="form-help">O envio em blocos conversacionais é aplicado globalmente a todos os agentes. Respostas curtas ficam inteiras; as maiores são divididas em até três blocos de no máximo 300 caracteres, com intervalo controlado pelo sistema. Se não couberem sem perda, a automação pede revisão humana.</p>
        <label class="field-label">Vocabulário de estilo (um item por linha)<textarea class="field-control" name="vocabulary">${esc(p.vocabulary.join('\n'))}</textarea></label>
        <label class="field-label">Até 3 exemplos revisados, separados por linha em branco<textarea class="field-control" name="examples">${esc(p.examples.join('\n\n'))}</textarea></label>
        <p class="form-help">Não inclua dados pessoais, preços ou regras comerciais nestes exemplos de estilo. O envio continua sujeito às permissões e à pausa global. Presença “digitando” depende do fornecedor e está indisponível nesta versão.</p>
        <div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Salvar perfil</button></div></form>`);
      const f=$('#conversation-profile-form');for(const key of ['tone','conciseness','emojis'])f.elements[key].value=p[key];
      formSubmit(f,async fd=>{await request(`/agents/${encodeURIComponent(id)}/conversation-policy`,{method:'PUT',body:{...p,enabled:fd.get('enabled')==='on',visit_booking_enabled:fd.get('visit_booking_enabled')==='on',tone:fd.get('tone'),conciseness:fd.get('conciseness'),emojis:fd.get('emojis'),context_minutes:Number(fd.get('context_minutes')),max_wait_seconds:Number(fd.get('max_wait_seconds')),vocabulary:String(fd.get('vocabulary')).split('\n').map(x=>x.trim()).filter(Boolean),examples:String(fd.get('examples')).split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean)}});closeModal();toast('Perfil salvo. Respostas pendentes anteriores foram invalidadas.','success');agents()});
    }catch(e){toast(e.message,'error')}
  }
  async function confirmDelete(type,id,refresh){if(!await askConfirm(`Excluir este ${type}?`,{title:'Excluir',confirmLabel:'Excluir',danger:true}))return;try{await request(`/${type==='agente'?'agents':'zapi/instances'}/${encodeURIComponent(id)}`,{method:'DELETE'});toast(`${type[0].toUpperCase()+type.slice(1)} excluído.`,'success');refresh()}catch(e){toast(e.message,'error')}}
  function connectionCredentialGuide(supplier, model){
    if(supplier==='wame'){
      const name=model==='official'?'API oficial':'API não oficial (QR Code)';
      return `<div class="credential-guide"><h3>WAME · ${name}</h3><p>No painel da WAME só aparecem <strong>Server</strong> e <strong>Key</strong>. O nome e o ID da conexão são inventados aqui.</p><ol><li>Cole o <strong>Server</strong> do painel no campo Server (ex.: https://us.api-wa.me).</li><li>Cole a <strong>Key</strong> do painel em <strong>Chave da instância</strong>.</li><li>Em <strong>Nome de identificação</strong>, invente um nome interno (ex.: WhatsApp loja).</li><li>Em <strong>ID da conexão</strong>, invente um id interno com letras, números, _ ou -. Não cole a Key.</li><li>Deixe desligada, no painel, a opção <strong>Exigir token de acesso</strong>.</li></ol>${model==='official'?'<p>Na API oficial, a Meta pode recusar texto livre fora da janela de 24 horas.</p>':''}</div>`;
    }
    if(model==='official')return '<div class="credential-guide"><h3>Z-API · API oficial</h3><p>A Z-API oferece API oficial, mas este modelo ainda não está implantado nesta plataforma. Escolha a API não oficial (QR Code) da Z-API, ou a WAME na API oficial ou por QR Code.</p></div>';
    return '<div class="credential-guide"><h3>Z-API · API não oficial (QR Code)</h3><p>No painel da Z-API, crie a instância do número. A API oficial da Z-API ainda não está implantada aqui.</p><ol><li>Copie o ID da instância para <strong>ID da conexão</strong>.</li><li>Copie o token da instância para <strong>Credencial de acesso</strong>.</li><li>Se o painel mostrar um token de cliente, cole em <strong>Credencial adicional</strong>. Se não existir, deixe vazio.</li><li>Depois de salvar, use <strong>Callbacks</strong>.</li></ol></div>';
  }
  async function instances(){const root=$('#page-content'),action='<button class="button button-primary" data-add-instance>＋ Adicionar conexão</button>',guides='<section class="card panel"><div class="panel-head"><div><h2>Fornecedores e modelos</h2><p>Z-API e WAME oferecem API oficial e API por QR Code. Na WAME, o painel entrega só Server e Key; nome e ID da conexão são criados aqui.</p></div></div><div class="credential-grid"><article class="credential-guide"><h3>Z-API</h3><p><span class="badge badge-good">Implantado</span> API não oficial (QR Code). ID da instância, token e token de cliente se o painel mostrar.</p><p><span class="badge badge-warn">Ainda não implantado</span> API oficial.</p></article><article class="credential-guide"><h3>WAME</h3><p><span class="badge badge-good">Implantado</span> API não oficial (QR Code) e API oficial.</p><p>Do painel: <strong>Server</strong> e <strong>Key</strong>. Aqui: invente nome e ID; cole Server e Key.</p></article></div></section>';root.innerHTML=pageHead('Conexões WhatsApp','Dois fornecedores, cada um com API oficial e API por QR Code.',action)+guides+loading();root.querySelector('[data-add-instance]').onclick=()=>instanceForm();try{const data=await request('/zapi/instances');const arr=Array.isArray(data)?data:(data?.items||[]);if(state.route!=='instances')return;const rows=arr.map(a=>`<tr><td><strong>${esc(a.label||a.name||'Conexão')}</strong><small>${esc(a.connection_label||'Conexão WhatsApp')}</small>${a.api_base_url?`<small>${esc(a.api_base_url)}</small>`:''}</td><td>${esc(a.instance_id||'—')}</td><td><span class="badge ${a.status==='connected'||a.connected===true?'badge-good':'badge-warn'}"><i class="status-dot ${a.status==='connected'||a.connected===true?'good':'status-neutral'}"></i>${esc(a.status||'Não verificado')}</span></td><td><span class="badge">Segredo oculto</span></td><td><div class="actions"><button class="small-button" data-policy="${esc(a.id)}">Agente e envio</button><button class="small-button" data-intervention="${esc(a.id)}">Intervenção humana</button><button class="small-button" data-webhooks="${esc(a.id)}">Callbacks</button><button class="small-button" data-refresh="${esc(a.id)}">Atualizar status</button><button class="small-button" data-send="${esc(a.id)}">Enviar mensagem</button><button class="small-button" data-delete="${esc(a.id)}">Excluir</button></div></td></tr>`).join('');root.innerHTML=pageHead('Conexões WhatsApp','Dois fornecedores, cada um com API oficial e API por QR Code.',action)+guides+`<div class="inline-alert">Na WAME, Server e Key vêm do painel. Nome e ID da conexão são internos desta plataforma.</div>`+table(['Conexão','ID no provedor','Status','Credenciais','Ações'],rows,'Adicione uma conexão WhatsApp para conectar o canal.');root.querySelector('[data-add-instance]').onclick=()=>instanceForm();$$('[data-policy]',root).forEach(b=>b.onclick=()=>instancePolicyForm(arr.find(x=>String(x.id)===b.dataset.policy)));$$('[data-webhooks]',root).forEach(b=>b.onclick=async()=>{try{const r=await request(`/zapi/instances/${encodeURIComponent(b.dataset.webhooks)}/webhooks`,{method:'POST'});toast(r.configured?'Callbacks configurados.':r.notice,r.configured?'success':'error')}catch(e){toast(e.message,'error')}});$$('[data-refresh]',root).forEach(b=>b.onclick=async()=>{b.disabled=true;try{const res=await request(`/zapi/instances/${encodeURIComponent(b.dataset.refresh)}/refresh-status`,{method:'POST'});if(res?.callback_url)toast(`Status atualizado. Configure manualmente a callback URL: ${res.callback_url}`,'success');else toast('Solicitação de atualização concluída.','success');instances()}catch(e){toast(e.message,'error');b.disabled=false}});$$('[data-send]',root).forEach(b=>b.onclick=()=>sendForm(b.dataset.send));$$('[data-delete]',root).forEach(b=>b.onclick=()=>confirmDelete('conexão',b.dataset.delete,instances));}catch(err){if(state.route==='instances')root.innerHTML=pageHead('Conexões WhatsApp','Dois fornecedores, cada um com API oficial e API por QR Code.',action)+guides+errorBox(err);}}
  function instanceForm(){openModal('Adicionar conexão WhatsApp',`<form id="instance-form"><fieldset class="agent-models"><legend>Fornecedor</legend><label class="check-line"><input type="radio" name="supplier" value="zapi" checked> Z-API</label><label class="check-line"><input type="radio" name="supplier" value="wame"> WAME</label></fieldset><fieldset class="agent-models"><legend>Modelo</legend><label class="check-line"><input type="radio" name="model" value="qr" checked> API não oficial (QR Code)</label><label class="check-line"><input type="radio" name="model" value="official"> API oficial</label></fieldset><p class="form-help" id="connection-offer-status"></p><div id="connection-credential-guide"></div><p class="muted-text">Credenciais são enviadas à API para salvar, nunca renderizadas de volta. Guarde-as com segurança.</p><label class="field-label" for="z-label">Nome de identificação</label><input class="field-control" id="z-label" name="label" required autocomplete="off" placeholder="Ex.: WhatsApp loja"><p class="form-help" id="z-label-help"></p><div id="z-server-wrap" hidden><label class="field-label" for="z-server">Server</label><input class="field-control" id="z-server" name="api_base_url" type="url" autocomplete="off" placeholder="https://us.api-wa.me"><p class="form-help">Copie o Server do painel WAME. Ex.: https://us.api-wa.me</p></div><label class="field-label" for="z-id">ID da conexão</label><input class="field-control" id="z-id" name="instance_id" required autocomplete="off" placeholder="Ex.: wame-loja-01"><p class="form-help" id="z-id-help"></p><label class="field-label" id="z-token-label" for="z-token">Credencial de acesso</label><input class="field-control" id="z-token" name="token" type="password" required autocomplete="new-password"><div id="z-client-wrap"><label class="field-label" for="z-client">Credencial adicional (se exigida)</label><input class="field-control" id="z-client" name="client_token" type="password" autocomplete="new-password"></div><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" id="connection-save" type="submit">Salvar conexão</button></div></form>`);const form=$('#instance-form');const syncConnectionForm=()=>{const supplier=form.querySelector('[name=supplier]:checked').value,model=form.querySelector('[name=model]:checked').value,wame=supplier==='wame',available=!(supplier==='zapi'&&model==='official');$('#connection-offer-status').textContent=available?(wame?(model==='official'?'WAME · API oficial. Implantado.':'WAME · API não oficial (QR Code). Implantado.'):'Z-API · API não oficial (QR Code). Implantado.'):'Z-API · API oficial ainda não está implantada. Escolha o QR Code da Z-API, ou a WAME no modelo oficial ou por QR Code.';$('#connection-credential-guide').innerHTML=connectionCredentialGuide(supplier,model);$('#z-label-help').textContent=wame?'Nome interno desta plataforma. Não vem do painel WAME.':'Nome interno desta plataforma.';$('#z-id-help').textContent=wame?'Inventado aqui. Letras, números, _ ou -. Não cole a Key do painel.':'ID copiado do painel da Z-API. Não cole o token aqui.';$('#z-token-label').textContent=wame?'Chave da instância (Key)':'Credencial de acesso';$('#z-server-wrap').hidden=!wame;$('#z-server').required=wame;$('#z-client-wrap').hidden=wame;$('#connection-save').disabled=!available;};form.querySelectorAll('[name=supplier],[name=model]').forEach(input=>input.onchange=syncConnectionForm);syncConnectionForm();formSubmit(form,async fd=>{const supplier=fd.get('supplier'),model=fd.get('model');if(supplier==='zapi'&&model==='official'){toast('A API oficial da Z-API ainda não está implantada.','error');return;}const provider=supplier==='zapi'?'zapi':(model==='official'?'wame_official':'wame_qr');const secrets=['token','client_token'];const payload={provider,label:fd.get('label'),instance_id:fd.get('instance_id'),token:fd.get('token'),client_token:String(provider).startsWith('wame')?null:fd.get('client_token'),api_base_url:String(provider).startsWith('wame')?fd.get('api_base_url'):null};try{const res=await request('/zapi/instances',{method:'POST',body:payload});if(res?.callback_url&&!res.webhook_configured){closeModal();openModal('URL de callback',`<p class="muted-text">Copie esta URL uma única vez e cadastre-a nos callbacks de mensagens recebidas. Ela contém um segredo de acesso.</p><label class="field-label" for="callback-url">Callback HTTPS</label><textarea class="field-control" id="callback-url" rows=3 readonly>${esc(res.callback_url)}</textarea><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Fechar</button><button class="button button-primary" id="copy-callback" type="button">Copiar URL</button></div>`);$('#copy-callback').onclick=async()=>{try{await navigator.clipboard.writeText(res.callback_url);toast('URL copiada. Guarde-a em local seguro.','success')}catch{const box=$('#callback-url');box.select();toast('Selecione e copie a URL manualmente.','error')}}}else{closeModal();toast(res?.webhook_configured?'Conexão salva; callback HTTPS configurado.':(res?.notice||'Conexão salva. Credenciais protegidas.'),'success');}}finally{secrets.forEach(k=>payload[k]='');fd.set('token','');fd.set('client_token','')}instances()});}
  async function instancePolicyForm(instance){try{const agents=await request('/agents');const globalOn=instance.global_sending_enabled===true;openModal('Agente e política de envio',`<form id="instance-policy-form"><p class="inline-alert">${globalOn?'Envio global liberado.':'Envio global pausado. Libere em Configurações → Envio WhatsApp antes de criar grupo, testar ou enviar.'}</p><label class="field-label" for="policy-agent">Agente responsável</label><select class="field-control" id="policy-agent" name="agent_id"><option value="">Sem agente — auto-resposta suspensa</option>${agents.map(a=>`<option value="${esc(a.id)}" ${instance.agent_id===a.id?'selected':''}>${esc(a.name)}${a.enabled?'':' (inativo)'}</option>`).join('')}</select><label class="check-line"><input name="sending_enabled" type="checkbox" ${instance.sending_enabled?'checked':''}>Liberar envio desta conexão</label><label class="field-label" for="policy-rate">Máximo de mensagens por minuto</label><input class="field-control" id="policy-rate" name="messages_per_minute" type="number" min="1" max="60" value="${esc(instance.messages_per_minute||10)}" required><p class="form-help">Esta conexão só envia se o envio global e este interruptor estiverem liberados. O agente precisa estar ativo e com auto-resposta habilitada.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Salvar política</button></div></form>`);formSubmit($('#instance-policy-form'),async fd=>{await request(`/zapi/instances/${encodeURIComponent(instance.id)}/policy`,{method:'PATCH',body:{agent_id:fd.get('agent_id')||null,sending_enabled:fd.get('sending_enabled')==='on',messages_per_minute:Number(fd.get('messages_per_minute'))}});closeModal();toast('Política salva.','success');instances()})}catch(e){toast(e.message,'error')}}
  function sendForm(id){const idempotencyKey=crypto.randomUUID();openModal('Enviar mensagem',`<form id="send-form"><label class="field-label" for="send-phone">Telefone (com código do país)</label><input class="field-control" id="send-phone" name="phone" type="tel" required placeholder="5511999999999"><label class="field-label" for="send-message">Mensagem</label><textarea class="field-control" id="send-message" name="message" required maxlength="4000"></textarea><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Enviar</button></div></form>`);formSubmit($('#send-form'),async fd=>{await request(`/zapi/instances/${encodeURIComponent(id)}/send-text`,{method:'POST',body:{phone:fd.get('phone'),message:fd.get('message'),idempotency_key:idempotencyKey}});closeModal();toast('Mensagem enfileirada; a aceitação e a entrega ainda serão verificadas.','success')});}
  async function conversations(){const root=$('#page-content');root.innerHTML=pageHead('Conversas','Acompanhe os atendimentos recebidos pelas conexões WhatsApp.')+loading();try{const data=await request('/conversations');state.conversations=Array.isArray(data)?data:(data?.items||[]);if(state.route!=='conversations')return;root.innerHTML=pageHead('Conversas','Acompanhe os atendimentos recebidos pelas conexões WhatsApp.')+`<section class="card conversation-layout"><div class="conversation-list"><div class="conversation-list-head"><input id="conversation-search" type="search" placeholder="Buscar conversa…" aria-label="Buscar conversa"></div><div id="conversation-items">${state.conversations.length?state.conversations.map(conv=>`<button class="conversation-item" data-conversation="${esc(conv.id)}"><strong>${esc(conv.contact_name||conv.name||conv.phone||'Conversa')}</strong><small><span class="badge ${conv.status==='open'?'badge-good':'badge-warn'}">${esc(conv.status||'sem estado')}</span> ${esc(conv.pause_reason||'')} · última mensagem: ${esc(conv.last_author_kind||conv.last_direction||'—')}</small><small>${conv.history_only?'<span class="badge badge-warn">Histórico</span> ':''}${esc(conv.last_message||conv.last_message_text||'Sem prévia de mensagem')}</small></button>`).join(''):empty('Nenhuma conversa encontrada','As conversas serão exibidas quando houver dados disponíveis.')}</div></div><section class="message-pane" aria-label="Mensagens da conversa"><div class="message-head" id="message-title">Selecione uma conversa</div><div id="messages-content" class="messages"><p class="message-empty">Selecione uma conversa para carregar as mensagens.</p></div></section></section>`;$$('[data-conversation]',root).forEach(b=>b.onclick=()=>loadMessages(b.dataset.conversation,b));$('#conversation-search').oninput=e=>$$('[data-conversation]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));}catch(e){if(state.route==='conversations')root.innerHTML=pageHead('Conversas','Acompanhe os atendimentos recebidos pelas conexões WhatsApp.')+errorBox(e)}}
  async function loadMessages(id,button){
    state.selectedConversation=id;$$('.conversation-item').forEach(b=>b.classList.toggle('selected',b===button));
    const box=$('#messages-content');box.innerHTML=loading();
    try{
      const [data,info]=await Promise.all([request(`/conversations/${encodeURIComponent(id)}/messages`),request(`/conversations/${encodeURIComponent(id)}/state`)]);
      if(state.selectedConversation!==id)return;
      $('#message-title').innerHTML=`<div><strong>${esc(button.querySelector('strong').textContent)}</strong><small> ${esc(info.status)} ${esc(info.pause_reason||'')}</small></div><div class="actions"><button class="small-button" id="conversation-controls">Controle da automação</button><button class="small-button" data-caction="takeover">Assumir</button><button class="small-button" data-caction="resume">Retomar IA</button><button class="small-button" data-caction="cancel">Pausar pendências</button><button class="small-button" id="human-reply">Responder</button><button class="small-button" id="refresh-conversation">Atualizar</button></div>`;
      $$('[data-caction]').forEach(b=>b.onclick=async()=>{if(b.dataset.caction==='resume'&&!(await askConfirm('Retomar IA? A automação aguardará nova mensagem do cliente.',{title:'Retomar automação',confirmLabel:'Retomar'})))return;b.disabled=true;try{await request(`/conversations/${encodeURIComponent(id)}/${b.dataset.caction}`,{method:'POST',body:{expected_revision:info.revision}});await loadMessages(id,button)}catch(e){toast(e.message,'error');b.disabled=false}});
      $('#conversation-controls').onclick=()=>conversationControls(id,info,button);$('#human-reply').onclick=()=>humanReplyForm(id,info,()=>loadMessages(id,button));$('#refresh-conversation').onclick=()=>loadMessages(id,button);
      const msgs=Array.isArray(data)?data:[];
      box.innerHTML=msgs.map(m=>`<div class="message-bubble ${m.direction==='outgoing'?'outgoing':''}">${esc(m.text||'')}<small>${esc(m.author_name||m.author_kind||m.direction)} · ${m.is_historical?'Histórico':esc(m.status)} · ${esc(m.is_historical?(m.original_timestamp_text||'Data ausente no arquivo'):m.created_at||'')}</small></div>`).join('')+`<div class="message-empty">Últimos envios: ${info.outbox.map(p=>`${esc(p.status)}${p.parts.length?' ('+p.parts.map(x=>esc(x.status)).join(', ')+')':''}`).join(' · ')||'nenhum'}</div>`;box.scrollTop=box.scrollHeight;
    }catch(e){if(state.selectedConversation===id)box.innerHTML=`<p class="message-empty" role="alert">${esc(e.message)}</p>`}
  }
  async function conversationControls(id,info,button){
    const c=info.controls||{},global=c.global||{},connection=c.connection||{},agent=c.agent||{},admin=['platform_admin','tenant_admin'].includes(state.role);
    const label=(value)=>({global_outbound_disabled:'Envio global pausado',connection_inactive:'Conexão desativada',connection_disconnected:'Conexão desconectada no provedor',connection_sending_paused:'Envio desta conexão pausado',webhook_not_configured:'Callback de mensagens não configurado',agent_unassigned:'Nenhum agente atribuído',agent_disabled:'Agente inativo',auto_reply_disabled:'Resposta automática desativada',instance_paused:'Conexão indisponível',instance_disconnected:'Conexão desconectada',contact_blocked:'Contato bloqueado ou sem autorização',conversation_paused:'Conversa pausada para atendimento humano',external_takeover:'Mensagem manual enviada pelo WhatsApp conectado',human_requested:'Cliente pediu atendimento humano',takeover:'Atendente assumiu a conversa',customer_cancel:'Pausa solicitada pelo cliente; uma nova mensagem pode retomar',intervention_requested:'Intervenção humana solicitada',consent_required:'Fora da janela de atendimento e sem consentimento registrado',stale_revision:'Resposta antiga cancelada',agent_disabled_or_unassigned:'Agente inativo ou não atribuído'})[value]||value;
    const row=(title,value,detail,action='')=>`<div class="control-status-row"><div><strong>${esc(title)}</strong><span class="badge ${value?'badge-good':'badge-warn'}">${value?'Liberado':'Bloqueado'}</span><small>${esc(detail)}</small></div>${action}</div>`;
    const blockers=(c.blockers||[]).map(x=>`<li>${esc(label(x))}</li>`).join('');
    const latest=(info.outbox||[]).slice(0,5).map(x=>`<li>${esc(x.status)}${x.last_error?` — ${esc(label(x.last_error))}`:''}${x.parts?.length?` (${x.parts.map(p=>esc(p.status)).join(', ')})`:''}</li>`).join('');
    const globalAction=admin?`<button class="small-button" data-control-global>${global.enabled?'Pausar globalmente':'Liberar envio global'}</button>`:'';
    const connectionAction=admin&&connection.id?`${connection.active?`<button class="small-button" data-control-connection>${connection.sending_enabled?'Pausar conexão':'Liberar conexão'}</button>`:''}${(!connection.active||connection.status!=='connected'||!connection.webhook_configured)?'<button class="small-button" data-control-open-connections>Ver conexão</button>':''}`:'';
    const agentAction=admin&&connection.id?`<button class="small-button" data-control-agent>${!agent.id?'Atribuir agente':agent.enabled&&agent.auto_reply_enabled?'Pausar agente':'Ativar respostas do agente'}</button>`:'';
    const resumeAction=info.status!=='open'||info.pause_reason?`<button class="small-button" data-control-resume>Retomar IA nesta conversa</button>`:'';
    const consentAction=admin&&(info.consent_status!=='granted'||info.opted_out)?`<button class="small-button" data-control-consent>Registrar nova autorização</button>`:'';
    const lastAuthor=({user:'cliente',operator:'equipe',assistant:'agente',system:'sistema'})[c.last_message_author]||'autor não identificado';
    const lastEvent=c.last_message_direction?`Última mensagem registrada: ${c.last_message_direction==='incoming'?'recebida do contato':'enviada pela equipe'} (${lastAuthor}).`:'';
    const webhook=c.processing?.webhook,model=c.processing?.model;
    const processSummary=webhook?`Webhook: ${webhook.processed?'processado':'pendente'} · tentativas ${webhook.attempts}${webhook.error?` · ${label(webhook.error)}`:''}.`: 'Nenhum webhook correlacionado à última mensagem.';
    const modelSummary=model?`Modelo: ${esc(model.status)}${model.attempts?.length?` · ${model.attempts.map(a=>`${esc(a.provider||'modelo')} ${esc(a.result||'')}`).join(' → ')}`:''}.`:'Nenhuma execução de modelo registrada para esta conversa.';
    const modelAction=admin&&model&&['failed','exhausted','trying_alternatives'].includes(model.status)?'<button class="small-button" data-control-open-model>Ver modelos</button>':'';
    openModal('Controle da automação',`<p class="form-help">Diagnóstico separado por escopo. Uma pausa nesta conversa não pausa outros contatos.</p><div class="automation-control-list">${row('Envio global',global.enabled,`Fonte: ${global.source==='painel'?'painel':'padrão do ambiente'}.`,globalAction)}${row('Conexão WhatsApp',connection.active&&connection.status==='connected'&&connection.sending_enabled,`${connection.label||'Conexão'} · ${connection.status||'sem status'} · callback ${connection.webhook_configured?'configurado':'não configurado'}.`,connectionAction)}${row('Agente',agent.enabled&&agent.auto_reply_enabled,agent.name?`${agent.name} · ${agent.enabled?'ativo':'inativo'} · respostas automáticas ${agent.auto_reply_enabled?'ativas':'desativadas'}.`:'Nenhum agente atribuído à conexão.',agentAction)}${row('Esta conversa',info.status==='open'&&!info.opted_out,`${info.status}${info.pause_reason?` · ${label(info.pause_reason)}`:''}. ${lastEvent}`,resumeAction)}${row('Permissão do contato',info.consent_status==='granted'||(!info.opted_out&&c.policy_denial!=='consent_required'),`Consentimento: ${info.consent_status||'desconhecido'}${info.opted_out?' · opt-out registrado':''}.`,consentAction)}</div>${blockers?`<section class="control-explanation"><strong>O que está impedindo a automação</strong><ul>${blockers}</ul></section>`:'<p class="inline-alert">Nenhum bloqueio de automação foi identificado agora. A próxima mensagem recebida deve iniciar um novo turno se chegar pela conexão configurada.</p>'}<section class="control-explanation"><strong>Recebimento e interpretação</strong><p>${esc(processSummary)}</p><p>${modelSummary}</p>${modelAction}</section><section class="control-explanation"><strong>Últimos envios</strong><ul>${latest||'<li>Nenhum envio registrado nesta conversa.</li>'}</ul><small>Envios com resultado desconhecido não são repetidos automaticamente. Reativar uma camada não reenfileira mensagens antigas.</small></section>`);
    $('#modal-body').querySelector('[data-control-global]')?.addEventListener('click',async()=>{const enable=!global.enabled;const msg=enable?'Liberar o envio global pode despachar mensagens que já estão pendentes em todas as conexões. Confirma?':'Pausar o envio global interrompe envios em todas as conexões. Confirma?';if(!(await askConfirm(msg,{title:enable?'Liberar envios reais':'Pausar envios',confirmLabel:enable?'Liberar':'Pausar',danger:enable})))return;try{await request('/settings/outbound',{method:'PUT',body:enable?{enabled:true,confirm_real_sends:true}:{enabled:false}});toast(enable?'Envio global liberado.':'Envio global pausado.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}});
    $('#modal-body').querySelector('[data-control-open-connections]')?.addEventListener('click',()=>{closeModal();go('instances')});
    $('#modal-body').querySelector('[data-control-open-model]')?.addEventListener('click',()=>{closeModal();go('model')});
    $('#modal-body').querySelector('[data-control-connection]')?.addEventListener('click',async()=>{const enable=!connection.sending_enabled;if(!(await askConfirm(`${enable?'Liberar':'Pausar'} esta conexão pode afetar todos os contatos atendidos por ela${enable?' e despachar mensagens pendentes':''}. Confirma?`,{title:enable?'Liberar conexão':'Pausar conexão',confirmLabel:enable?'Liberar':'Pausar',danger:enable})))return;try{await request(`/zapi/instances/${encodeURIComponent(connection.id)}/policy`,{method:'PATCH',body:{agent_id:agent.id||null,sending_enabled:enable}});toast('Política da conexão atualizada.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}});
    $('#modal-body').querySelector('[data-control-agent]')?.addEventListener('click',async()=>{if(!agent.id){try{const agents=await request('/agents');const available=agents.filter(a=>a.enabled&&a.auto_reply_enabled);if(!available.length){toast('Não há agente ativo com resposta automática habilitada.','error');return}openModal('Atribuir agente à conexão',`<form id="control-assign-agent"><label class="field-label" for="control-agent-select">Agente</label><select class="field-control" id="control-agent-select" name="agent_id" required>${available.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select><p class="form-help">A atribuição vale para todos os contatos desta conexão.</p><div class="form-actions"><button class="button button-secondary" type="button" data-back-controls>Voltar</button><button class="button button-primary" type="submit">Atribuir agente</button></div></form>`);$('#modal-body').querySelector('[data-back-controls]').onclick=()=>conversationControls(id,info,button);formSubmit($('#control-assign-agent'),async fd=>{if(!(await askConfirm('Atribuir este agente habilitado pode iniciar respostas automáticas para novas mensagens desta conexão. Confirma?',{title:'Atribuir agente',confirmLabel:'Atribuir',danger:true})))return;try{await request(`/zapi/instances/${encodeURIComponent(connection.id)}/policy`,{method:'PATCH',body:{agent_id:fd.get('agent_id'),sending_enabled:connection.sending_enabled}});toast('Agente atribuído à conexão.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}})}catch(e){toast(e.message,'error')}return}const enable=!(agent.enabled&&agent.auto_reply_enabled);if(!(await askConfirm(`${enable?'Ativar':'Pausar'} este agente afeta todas as conexões que o utilizam. Confirma?`,{title:enable?'Ativar respostas do agente':'Pausar agente',confirmLabel:enable?'Ativar':'Pausar',danger:enable})))return;try{await request(`/agents/${encodeURIComponent(agent.id)}`,{method:'PUT',body:{enabled:enable,auto_reply_enabled:enable}});toast('Estado do agente atualizado.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}});
    $('#modal-body').querySelector('[data-control-resume]')?.addEventListener('click',async()=>{if(!(await askConfirm('Retomar somente esta conversa. A IA aguardará uma nova mensagem do cliente; mensagens antigas não serão reenviadas.',{title:'Retomar IA nesta conversa',confirmLabel:'Retomar'})))return;try{await request(`/conversations/${encodeURIComponent(id)}/resume`,{method:'POST',body:{expected_revision:info.revision}});toast('Automação retomada nesta conversa.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}});
    $('#modal-body').querySelector('[data-control-consent]')?.addEventListener('click',()=>{openModal('Registrar nova autorização',`<form id="control-consent-form"><p class="inline-alert">Use somente se o cliente autorizou novamente o contato. Não use esta ação para apagar um opt-out sem nova autorização comprovável. Registrar consentimento não retoma uma conversa pausada nem envia mensagens.</p><label class="field-label" for="control-consent-evidence">Evidência da autorização</label><textarea class="field-control" id="control-consent-evidence" name="evidence" required minlength="5" maxlength="1000" placeholder="Registre quando e como o cliente autorizou"></textarea><div class="form-actions"><button class="button button-secondary" type="button" data-back-controls>Voltar</button><button class="button button-primary" type="submit">Salvar autorização</button></div></form>`);$('#modal-body').querySelector('[data-back-controls]').onclick=()=>conversationControls(id,info,button);formSubmit($('#control-consent-form'),async fd=>{try{await request(`/conversations/${encodeURIComponent(id)}/consent`,{method:'POST',body:{evidence:fd.get('evidence')}});toast('Nova autorização registrada; nenhuma mensagem foi enviada.','success');closeModal();await loadMessages(id,button)}catch(e){toast(e.message,'error')}})});
  }
  function humanReplyForm(id,info,refresh){
    const key=crypto.randomUUID();openModal('Assumir e responder',`<form id="human-reply-form"><label class="field-label">Resposta<textarea class="field-control" name="message" required maxlength="4000"></textarea></label><p class="form-help">A IA será pausada antes de enfileirar sua resposta. O envio respeita as permissões do contato e a pausa global. Atualize a conversa se ela mudar antes de enviar.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Assumir e enfileirar</button></div></form>`);
    formSubmit($('#human-reply-form'),async fd=>{await request(`/conversations/${encodeURIComponent(id)}/messages`,{method:'POST',body:{expected_revision:info.revision,message:fd.get('message'),idempotency_key:key}});closeModal();toast('Resposta enfileirada. A IA continua pausada.','success');refresh()});
  }
  async function knowledge(){
    const root=$('#page-content'),action='<button class="button button-secondary" data-search-settings>Configurar busca</button> <button class="button button-primary" data-upload>＋ Enviar documento</button>';
    root.innerHTML=pageHead('Conhecimento','Salve documentos e disponibilize-os para busca quando estiverem indexados.',action)+loading();
    try{
      const data=await request('/knowledge/documents');if(state.route!=='knowledge')return;
      const rows=data.map(x=>`<tr><td><strong>${esc(x.filename)}</strong></td><td>${esc(x.mime_type)}</td><td><span class="badge ${x.status==='indexed'?'badge-good':''}">${x.status==='indexed'?'Disponível para busca':x.status==='pending_index'?'Aguardando indexação':esc(x.status)}</span></td><td>${x.status!=='indexed'?`<button class="small-button" data-index-doc="${esc(x.id)}">Indexar para busca</button>`:''}</td></tr>`).join('');
      root.innerHTML=pageHead('Conhecimento','Salvar não envia o conteúdo a provedores. A indexação usa o serviço de busca configurado.',action)+table(['Documento','Tipo','Status','Ações'],rows,'Envie documentos para compor a base.');
      $('[data-upload]',root).onclick=uploadForm;$('[data-search-settings]',root).onclick=searchSettingsForm;
      $$('[data-index-doc]',root).forEach(b=>b.onclick=async()=>{if(!(await askConfirm('Indexar envia o texto extraído ao serviço de embeddings configurado para esta empresa. Continuar?',{title:'Indexar documento',confirmLabel:'Indexar'})))return;b.disabled=true;try{await request('/knowledge/documents/'+encodeURIComponent(b.dataset.indexDoc)+'/index',{method:'POST'});toast('Documento disponível para busca.','success');knowledge();}catch(e){toast(e.message,'error');b.disabled=false;}});
    }catch(e){if(state.route==='knowledge')root.innerHTML=pageHead('Conhecimento','Documentos',action)+errorBox(e);}
  }
  async function searchSettingsForm(){
    let c,connections;try{[c,connections]=await Promise.all([request('/knowledge/documents/search-settings'),request('/llm/connections')]);}catch(e){toast(e.message,'error');return;}
    openModal('Configurar busca da base',`<form id="search-settings-form"><p class="form-help">Selecione uma conexão cadastrada para aproveitar sua chave. O modelo de embeddings é diferente do modelo de conversa. Salvar não chama fornecedores.</p><label class="field-label" for="search-connection">Conexão da busca</label><select class="field-control" id="search-connection" name="connection_id"><option value="">Configuração manual / chave própria</option>${connections.map(x=>`<option value="${esc(x.id)}" ${!x.enabled||x.resolved_protocol==='anthropic'?'disabled':''}>${esc(x.name)} — ${esc(x.provider)}${!x.enabled?' (desativada)':x.resolved_protocol==='anthropic'?' (sem embeddings compatíveis)':''}</option>`).join('')}</select><div id="search-manual"><label class="field-label" for="search-base">URL base HTTPS</label><input class="field-control" id="search-base" name="base_url" type="url" value="${esc(c.base_url||'')}"><label class="field-label" for="search-key">Chave da busca (vazio preserva a chave própria atual)</label><input class="field-control" id="search-key" name="api_key" type="password" autocomplete="new-password"></div><label class="field-label" for="search-model">Modelo de embeddings</label><input class="field-control" id="search-model" name="model" required maxlength="160" value="${esc(c.model||'')}"><p class="form-help" id="search-connection-help"></p><p class="form-help">A busca exige 1536 dimensões. Nem toda conexão oferece embeddings. A seleção não confirma acesso ao modelo; índices existentes exigem preservar endpoint/modelo.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Salvar configuração</button></div></form>`);
    const f=$('#search-settings-form');f.elements.connection_id.value=c.connection_id||'';
    function update(suggest){const row=connections.find(x=>x.id===f.elements.connection_id.value),linked=!!row;$('#search-manual',f).hidden=linked;f.elements.base_url.required=!linked;f.elements.base_url.disabled=linked;f.elements.api_key.disabled=linked;f.elements.api_key.required=!linked&&(c.source!=='dedicated'||!!c.connection_id);$('#search-connection-help',f).textContent=linked?'A chave será lida da conexão no servidor, sem cópia ou novo cadastro. Alterações de chave na conexão serão aproveitadas.':'Use uma chave própria apenas se preferir uma configuração independente.';if(suggest&&linked){if(row.resolved_protocol==='gemini'||row.provider==='gemini')f.elements.model.value='gemini-embedding-001';else if(row.provider==='openai')f.elements.model.value='text-embedding-3-small';else f.elements.model.value='';}}
    update(false);f.elements.connection_id.onchange=()=>update(true);
    formSubmit(f,async fd=>{const payload={model:fd.get('model')};if(fd.get('connection_id'))payload.connection_id=fd.get('connection_id');else{payload.base_url=fd.get('base_url');if(String(fd.get('api_key')||'').trim())payload.api_key=String(fd.get('api_key')).trim();}try{await request('/knowledge/documents/search-settings',{method:'PUT',body:payload});closeModal();toast('Configuração de busca salva.','success');}finally{payload.api_key='';fd.set('api_key','');}});
  }
  function uploadForm(){openModal('Salvar documento',`<form id="upload-form"><label class="field-label" for="doc-file">Arquivo</label><input class="field-control" id="doc-file" name="file" type="file" required><p class="form-help">O texto extraído será salvo nesta empresa. O arquivo original não é armazenado. A indexação para busca é uma etapa separada.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Salvar documento</button></div></form>`);formSubmit($('#upload-form'),async fd=>{await request('/knowledge/documents',{method:'POST',body:fd,form:true});closeModal();toast('Documento salvo. Aguardando indexação.','success');knowledge()});}

  const llmUI=window.OrchestraLlmUI.create({request,esc,pageHead,loading,errorBox,table,openModal,closeModal,formSubmit,toast,askConfirm,getRoute:()=>state.route});
  async function model(){await llmUI.render($('#page-content'));}
  async function tenants(){const root=$('#page-content');if(state.role!=='platform_admin'){go('dashboard');return}const action='<button class="button button-primary" data-add-tenant>＋ Nova empresa</button>';root.innerHTML=pageHead('Empresas','Gerencie os espaços de trabalho da plataforma.',action)+loading();try{const data=await request('/tenants');const arr=Array.isArray(data)?data:(data?.items||[]);if(state.route!=='tenants')return;const rows=arr.map(t=>`<tr><td><strong>${esc(t.name||t.tenant_name||'Empresa')}</strong></td><td>${esc(t.id||'—')}</td><td>${esc(t.created_at||'—')}</td><td><span class="badge ${t.status==='active'?'badge-good':''}">${esc(t.status||'Ativa')}</span></td><td><button class="small-button" data-select-tenant="${esc(t.id)}" data-select-name="${esc(t.name||t.tenant_name||'Empresa')}">${String(t.id)===String(state.tenantId)?'Selecionada':'Selecionar'}</button></td></tr>`).join('');root.innerHTML=pageHead('Empresas','Gerencie os espaços de trabalho da plataforma.',action)+table(['Empresa','ID','Criada em','Status','Contexto'],rows,'Nenhuma empresa cadastrada.');root.querySelector('[data-add-tenant]').onclick=tenantForm;$$('[data-select-tenant]',root).forEach(b=>b.onclick=()=>selectTenant(b.dataset.selectTenant,b.dataset.selectName));}catch(e){if(state.route==='tenants')root.innerHTML=pageHead('Empresas','Gerencie os espaços de trabalho da plataforma.',action)+errorBox(e)}}
  function selectTenant(id,name){state.tenantId=String(id);state.tenant=name||'';sessionStorage.setItem('zapia_tenant_id',state.tenantId);sessionStorage.setItem('zapia_tenant',state.tenant);toast('Empresa selecionada.','success');setLoggedIn(true);if(state.route==='tenants')tenants();else go('dashboard')}
  function tenantForm(){openModal('Nova empresa',`<form id="tenant-form"><label class="field-label" for="tenant-name-new">Nome da empresa</label><input class="field-control" id="tenant-name-new" name="name" required><label class="field-label" for="tenant-slug">Slug</label><input class="field-control" id="tenant-slug" name="slug" minlength="2" maxlength="80" pattern="[a-z0-9]+(-[a-z0-9]+)*" title="Use letras minúsculas, números e hífens, sem espaços ou acentos." required><label class="field-label" for="owner-name">Nome do responsável</label><input class="field-control" id="owner-name" name="owner_name" required><label class="field-label" for="owner-email">E-mail do responsável</label><input class="field-control" id="owner-email" name="owner_email" type="email" required><label class="field-label" for="owner-password">Senha do responsável</label><input class="field-control" id="owner-password" name="owner_password" type="password" minlength="12" maxlength="256" autocomplete="new-password" required><p class="form-help">A senha do responsável deve ter pelo menos 12 caracteres.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Criar empresa</button></div></form>`);formSubmit($('#tenant-form'),async fd=>{const created=await request('/tenants',{method:'POST',body:{name:fd.get('name'),slug:fd.get('slug'),owner_name:fd.get('owner_name'),owner_email:fd.get('owner_email'),owner_password:fd.get('owner_password')}});if(created?.id)selectTenant(created.id,created.name||fd.get('name'));closeModal();toast('Empresa criada.','success');tenants()})}
  async function settings(){
    const root=$('#page-content'),admin=['platform_admin','tenant_admin'].includes(state.role);
    root.innerHTML=pageHead('Configurações','Gerencie sua sessão e o acesso à empresa.')+`<div class="grid settings-grid"><section class="card panel"><div class="panel-head"><div><h2>Espaço de trabalho</h2><p>Contexto associado à sua sessão atual.</p></div></div><dl class="detail-list"><dt>Empresa</dt><dd>${esc(state.tenant||'—')}</dd><dt>Perfil</dt><dd>${esc(state.role||'—')}</dd><dt>Conexão</dt><dd><span class="badge badge-teal">WhatsApp</span></dd></dl></section>${admin?`<section class="card panel"><div class="panel-head"><div><h2>Envio WhatsApp</h2><p>Freio global da plataforma. Mesmo com envio liberado na conexão, nada sai se este interruptor estiver pausado.</p></div><span id="outbound-badge" class="badge">…</span></div><p id="outbound-help" class="form-help">Carregando estado do envio…</p><div class="form-actions"><button class="button button-primary" id="outbound-toggle" type="button" disabled>…</button></div></section><section class="card panel"><div class="panel-head"><div><h2>Usuários da empresa</h2><p>Cadastre administradores e operadores. Cada pessoa entra com seu próprio e-mail e senha.</p></div><button class="button button-primary" id="add-user">＋ Adicionar usuário</button></div><div id="users-list">${loading()}</div></section>`:''}<section class="card panel"><div class="panel-head"><div><h2>Segurança</h2><p>Encerre esta sessão neste navegador.</p></div></div><button id="settings-logout" class="button button-secondary">Sair da conta</button></section></div>`;
    $('#settings-logout').onclick=logout;
    if(!admin)return;
    $('#add-user').onclick=()=>userForm();
    const paintOutbound=status=>{
      const on=!!status.enabled;
      $('#outbound-badge').className=on?'badge badge-good':'badge badge-warn';
      $('#outbound-badge').textContent=on?'Liberado':'Pausado';
      $('#outbound-help').textContent=on
        ?`Envios reais estão liberados (controle pelo ${status.source==='painel'?'painel':'ambiente'}). Cada conexão ainda precisa de “Liberar envio desta conexão”.`
        :'Envios reais estão pausados. Liberar aqui permite criar grupo, teste e mensagens nas conexões que também estiverem liberadas.';
      const button=$('#outbound-toggle');
      button.disabled=false;
      button.textContent=on?'Pausar envio global':'Liberar envio global';
      button.className=on?'button button-secondary':'button button-primary';
      button.onclick=async()=>{
        if(on){
          if(!(await askConfirm('Pausar o envio global agora? Grupos, testes e mensagens deixam de sair até nova liberação.',{title:'Pausar envio',confirmLabel:'Pausar envio',danger:true})))return;
          try{paintOutbound(await request('/settings/outbound',{method:'PUT',body:{enabled:false}}));toast('Envio global pausado.','success')}catch(e){toast(e.message,'error')}
          return;
        }
        if(!(await askConfirm('Liberar envio global permite WhatsApp real: mensagens, criação de grupo e testes. Continuar?',{title:'Liberar envio global',confirmLabel:'Liberar envio',danger:true})))return;
        try{paintOutbound(await request('/settings/outbound',{method:'PUT',body:{enabled:true,confirm_real_sends:true}}));toast('Envio global liberado.','success')}catch(e){toast(e.message,'error')}
      };
    };
    try{paintOutbound(await request('/settings/outbound'))}catch(e){$('#outbound-help').textContent=e.message||'Não foi possível ler o envio global.';$('#outbound-badge').textContent='Indisponível';$('#outbound-badge').className='badge badge-bad'}
    try{const rows=await request('/users');$('#users-list').innerHTML=rows.map(u=>`<div class="list-row"><div><strong>${esc(u.full_name)}</strong><small class="muted-text">${esc(u.email)} · ${u.role==='tenant_admin'?'Administrador':'Operador'} · ${u.is_active?'Ativo':'Desativado'}</small></div>${u.id!==JSON.parse(atob(state.token.split('.')[1])).sub?`<button class="small-button" data-user-toggle="${esc(u.id)}" data-active="${u.is_active}">${u.is_active?'Desativar':'Ativar'}</button>`:''}</div>`).join('')||empty('Nenhum usuário','Adicione um usuário para compartilhar o acesso com segurança.');$$('[data-user-toggle]').forEach(button=>button.onclick=async()=>{try{await request(`/users/${encodeURIComponent(button.dataset.userToggle)}`,{method:'PATCH',body:{is_active:button.dataset.active!=='true'}});settings()}catch(e){toast(e.message,'error')}});}catch(e){$('#users-list').innerHTML=errorBox(e)}
  }
  function userForm(){openModal('Adicionar usuário à empresa',`<form id="tenant-user-form"><label class="field-label">Nome<input class="field-control" name="full_name" required minlength="2" maxlength="160"></label><label class="field-label">E-mail<input class="field-control" name="email" type="email" required maxlength="320"></label><label class="field-label">Senha inicial (mínimo 12 caracteres)<input class="field-control" name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label class="field-label">Perfil<select class="field-control" name="role"><option value="operator">Operador — atendimento</option><option value="tenant_admin">Administrador — configura empresa e usuários</option></select></label><p class="form-help">O usuário poderá entrar com este e-mail e senha. Compartilhe a senha inicial por um canal seguro.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Criar usuário</button></div></form>`);formSubmit($('#tenant-user-form'),async fd=>{await request('/users',{method:'POST',body:{full_name:fd.get('full_name'),email:fd.get('email'),password:fd.get('password'),role:fd.get('role')}});fd.set('password','');closeModal();toast('Usuário criado.','success');settings()});}

  async function interventionRoutingForm(id){
    try{
      const c=await request(`/zapi/instances/${encodeURIComponent(id)}/intervention-routing`);
      const states={pending:'Pendente: a organização ainda precisa testar e confirmar o grupo.',test_sent:'Teste enviado: confirme que chegou ao grupo correto.',validated:'Validado pela organização.'};
      openModal('Intervenção humana — grupo da equipe',`<p class="muted-text">Crie o grupo no WhatsApp ou, se o provedor oferecer esse recurso, use a criação manual abaixo. Inclua o número conectado ao provedor e os atendentes. A criação nunca é automática. Cadastre o identificador do grupo e os telefones autorizados a assumir.</p><p class="form-help"><strong>Status:</strong> ${esc(states[c.validation_status]||'Pendente')}</p><p class="form-help">${c.webhook_configured?"Callback de mensagens recebidas configurado.":"Configure os callbacks de mensagens recebidas na conexão antes de validar o grupo."}</p>${c.can_create_group?'<div class="form-actions"><button class="button button-secondary" id="intervention-create-group" type="button">Criar grupo via API</button></div>':''}<form id="intervention-routing-form"><label class="field-label" for="intervention-group">Identificador do grupo</label><input class="field-control" id="intervention-group" name="group_id" value="${esc(c.group_id||'')}" required maxlength="240" placeholder="Ex.: 120363...-group"><label class="field-label" for="intervention-staff">Telefones autorizados (um por linha, com código do país)</label><textarea class="field-control" id="intervention-staff" name="staff_phones" rows="5" required placeholder="5511999999999">${esc((c.staff_phones||[]).join('\n'))}</textarea><p class="form-help">Somente esses números poderão assumir com <code>ASSUMINDO 123456</code>. Alterar grupo ou lista invalida a confirmação anterior.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Fechar</button><button class="button button-primary" type="submit">Salvar configuração</button></div></form><div class="form-actions"><button class="button button-secondary" id="intervention-test" type="button">Enviar mensagem de teste</button>${c.validation_status==='test_sent'?'<button class="button button-primary" id="intervention-confirm" type="button">Confirmar recebimento no grupo</button>':''}</div><p class="form-help">O teste envia uma mensagem real ao grupo. A configuração só será ativada depois que a organização confirmar que recebeu a mensagem no grupo correto.</p>`);
      const createButton=$('#intervention-create-group');if(createButton)createButton.onclick=()=>createInterventionGroupForm(id);
      formSubmit($('#intervention-routing-form'),async fd=>{const saved=await request(`/zapi/instances/${encodeURIComponent(id)}/intervention-routing`,{method:'PUT',body:{group_id:fd.get('group_id'),staff_phones:String(fd.get('staff_phones')).split('\n').map(x=>x.trim()).filter(Boolean)}});toast(saved.validation_status==='validated'?'Configuração salva; grupo permanece validado.':'Configuração salva. O grupo continua pendente de teste e confirmação.','success');interventionRoutingForm(id)});
      $('#intervention-test').onclick=async()=>{if(!(await askConfirm('Isso enviará uma mensagem real para o grupo configurado. Continuar?',{title:'Mensagem de teste',confirmLabel:'Enviar teste'})))return;try{await request(`/zapi/instances/${encodeURIComponent(id)}/intervention-routing/test`,{method:'POST'});toast('Teste enviado. Confira o grupo e confirme o recebimento.','success');interventionRoutingForm(id)}catch(e){toast(e.message,'error')}};
      const confirmButton=$('#intervention-confirm');if(confirmButton)confirmButton.onclick=async()=>{if(!(await askConfirm('Você confirmou que a mensagem de teste chegou ao grupo correto?',{title:'Validar grupo',confirmLabel:'Confirmar recebimento'})))return;try{await request(`/zapi/instances/${encodeURIComponent(id)}/intervention-routing/confirm`,{method:'POST',body:{confirmed_received:true}});closeModal();toast('Grupo validado. A equipe poderá receber alertas de intervenção.','success')}catch(e){toast(e.message,'error')}};
    }catch(e){toast(e.message,'error')}
  }

  function createInterventionGroupForm(id){
    openModal('Criar grupo de atendimento',`<p class="inline-alert"><strong>Esta ação cria um grupo real no WhatsApp e adiciona os números informados.</strong> Ela só ocorre após você confirmar o formulário. A criação do grupo não ativa os alertas; o teste e a validação continuam separados.</p><form id="intervention-create-group-form"><label class="field-label">Nome do grupo<input class="field-control" name="group_name" required minlength="2" maxlength="120" placeholder="Atendimento da empresa"></label><label class="field-label">Telefones dos atendentes (um por linha, com código do país)<textarea class="field-control" name="phones" required rows="5" placeholder="5511999999999"></textarea></label><label class="check-line"><input name="confirmed_not_connected_number" type="checkbox" required>Confirmei que a lista não inclui o número conectado a esta conexão.</label><label class="check-line"><input id="intervention-auto-invite" name="auto_invite" type="checkbox">Enviar convites privados a participantes que não puderem ser adicionados diretamente.</label><label class="check-line"><input name="confirm_auto_invites" type="checkbox">Se marquei a opção acima, autorizo o envio desses convites privados.</label><p class="form-help">Convites privados ficam desligados por padrão. Se a resposta da API for incerta, confira no WhatsApp antes de tentar novamente para evitar criar grupos duplicados.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Cancelar</button><button class="button button-primary" type="submit">Criar grupo agora</button></div></form>`);
    formSubmit($('#intervention-create-group-form'),async fd=>{
      if(!(await askConfirm('Criar agora um grupo real e adicionar os participantes informados?',{title:'Criar grupo',confirmLabel:'Criar agora',danger:true})))return;
      const button=$('#intervention-create-group-form [type=submit]');if(button)button.disabled=true;
      const result=await request(`/zapi/instances/${encodeURIComponent(id)}/intervention-routing/create-group`,{method:'POST',body:{group_name:fd.get('group_name'),phones:String(fd.get('phones')).split('\n').map(x=>x.trim()).filter(Boolean),auto_invite:fd.get('auto_invite')==='on',confirmed_not_connected_number:fd.get('confirmed_not_connected_number')==='on',confirm_auto_invites:fd.get('confirm_auto_invites')==='on'}});
      const invite=(()=>{try{const u=new URL(result.invitation_link);return u.protocol==='https:'&&u.hostname==='chat.whatsapp.com'?u.href:''}catch{return ''}})();
      closeModal();openModal('Grupo criado — validação pendente',`<p>O grupo foi criado. Identificador: <strong>${esc(result.group_id)}</strong></p>${invite?`<p><a href="${esc(invite)}" target="_blank" rel="noopener noreferrer">Abrir convite do grupo</a></p>`:''}<p class="form-help">A configuração continua pendente. Confira o grupo e os participantes no WhatsApp; depois envie o teste pelo painel e confirme o recebimento.</p><div class="form-actions"><button class="button button-secondary" type="button" data-close-modal>Fechar</button><button class="button button-primary" id="continue-intervention-setup" type="button">Continuar configuração</button></div>`);
      $('#continue-intervention-setup').onclick=()=>interventionRoutingForm(id);
    });
  }

  $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]'),error=$('#login-error');error.textContent='';button.disabled=true;button.textContent='Entrando…';try{const d=await request('/auth/login',{method:'POST',body:{email:$('#login-email').value,password:$('#login-password').value}});if(!d?.access_token)throw new Error('Resposta de login sem token de acesso.');state.token=d.access_token;state.role=d.role||'';state.tenant=d.tenant_name||'';state.tenantId=d.tenant_id?String(d.tenant_id):'';sessionStorage.setItem('zapia_tenant_id',state.tenantId);sessionStorage.setItem('zapia_token',state.token);sessionStorage.setItem('zapia_role',state.role);sessionStorage.setItem('zapia_tenant',state.tenant);$('#login-password').value='';state.route='dashboard';if(!location.hash)history.replaceState(null,'','#dashboard');setLoggedIn(true);wireNav();render();}catch(err){error.textContent=err.message||'Não foi possível entrar.';}finally{button.disabled=false;button.innerHTML='Entrar <span aria-hidden="true">→</span>'}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-intervention]');if(b)interventionRoutingForm(b.dataset.intervention)});
  window.addEventListener('hashchange',()=>{if(state.token)render()});
  if(state.token){setLoggedIn(true);wireNav();render()}else setLoggedIn(false);
})();
